func (q *Queries) ListWorkspaceTemplatesForUser(ctx context.Context, userID pgtype.UUID) ([]ListWorkspaceTemplatesForUserRow, error) {
	rows, err := q.db.Query(ctx, listWorkspaceTemplatesForUser, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListWorkspaceTemplatesForUserRow{}
	for rows.Next() {
		var i ListWorkspaceTemplatesForUserRow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.Name,
			&i.SourceName,
			&i.Report,
			&i.CreatedAt,
			&i.WorkspaceName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

